(()=>{"use strict";!function(){const t=document.getElementById("timer-days"),e=document.getElementById("timer-hours"),n=document.getElementById("timer-minutes"),o=document.getElementById("timer-seconds");let m;m=setInterval(()=>{let{timeRemaining:r,days:s,hours:i,minutes:a,seconds:d}=(()=>{let t=(new Date("21 February 2026").getTime()-(new Date).getTime())/1e3;return{timeRemaining:t,days:Math.floor(t/3600/24),hours:Math.floor(t/3600%24),minutes:Math.floor(t/60%60),seconds:Math.floor(t%60)}})();t.textContent=s<10?"0"+s:s,e.textContent=i<10?"0"+i:i,n.textContent=a<10?"0"+a:a,o.textContent=d<10?"0"+d:d,r<=0&&(t.textContent="00",e.textContent="00",n.textContent="00",o.textContent="00",clearInterval(m))},1e3)}()})();